mapper.select:
SELECT CASE WHEN A.SUBMIT_NO IS NULL THEN 'Y' ELSE 'N' END AS NEW_SUBMIT_NO_YN
  FROM DRWBAK_REQSTDOC_CMMN A 
 WHERE A.COMPANY_CODE = #{COMPANY_CODE}
   AND A.PRESENTN_NO = #{PRESENTN_NO}
   AND A.DIVISION_CODE = #{DIVISION_CODE}

mapper.update:
UPDATE DRWBAK_REQSTDOC_CMMN A
   SET A.SUBMIT_NO = (SELECT A.PRESENTN_NO||TO_CHAR(SYSDATE, 'YY')||LPAD(B.CURRENT_NO, 6, '0') AS SUBMIT_NO
                        FROM COMPANY A
                       INNER JOIN CSMHSE_SUBMIT_NO_MST B
                          ON A.COMPANY_CODE = B.COMPANY_CODE
                       WHERE A.COMPANY_CODE = #{COMPANY_CODE}
                         AND B.YY = TO_CHAR(SYSDATE, 'YY'))
       ,A.EXECUT_AT = NULL
 WHERE A.COMPANY_CODE = #{COMPANY_CODE}
   AND A.PRESENTN_NO = #{PRESENTN_NO}

